import React, { useState } from 'react';
import { Line } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend } from 'chart.js';
ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend);

export default function LmsDashboard() {
  const [stats] = useState({
    totalStudents: '1,250',
    totalTeachers: '950',
    activeClasses: '650',
    inactiveStudents: '350'
  });

  const [growthData] = useState({
    labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May'],
    datasets: [{
      label: 'Enrollment Growth',
      data: [10, 32, 25, 48, 80],
      borderColor: '#16a34a',
      backgroundColor: 'rgba(22, 163, 74, 0.1)',
      tension: 0.4,
      fill: true
    }]
  });

  const [schedule] = useState({
    days: ['Sun', 'Mon', 'Wed', 'Thu', 'Fri'],
    slots: [
      { time: '11:30', Sun: 'Math 101', Mon: '', Wed: '', Thu: '', Fri: '' },
      { time: '1:30', Sun: '', Mon: '', Wed: 'Science', Thu: '', Fri: '' },
      { time: '1:00', Sun: 'Wedneddiel', Mon: '', Wed: '', Thu: 'English Lit', Fri: '' },
      { time: '2:00', Sun: '', Mon: '', Wed: '', Thu: '', Fri: 'History Class' }
    ]
  });

  const [students] = useState([
    { name: 'Ruwan Name', status: 'Active' },
    { name: 'John Name', status: 'Inactive' },
    { name: 'Sama Name', status: 'Active' }
  ]);

  return (
    <div style={{ fontFamily: 'sans-serif', display: 'flex', flexDirection: 'column', gap: '25px' }}>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '20px' }}>
        {[
          { t: 'Total Students', v: stats.totalStudents, c: '#0f172a' },
          { t: 'Total Teachers', v: stats.totalTeachers, c: '#0f172a' },
          { t: 'Active Classes', v: stats.activeClasses, c: '#16a34a' },
          { t: 'Inactive Students', v: stats.inactiveStudents, c: '#dc2626' }
        ].map((item, i) => (
          <div key={i} style={{ background: '#fff', padding: '20px', borderRadius: '12px', boxShadow: '0 4px 12px rgba(0,0,0,0.03)', borderTop: `4px solid ${item.c}` }}>
            <p style={{ color: '#64748b', fontSize: '13px', fontWeight: '500', margin: '0 0 6px 0' }}>{item.t}</p>
            <h2 style={{ margin: 0, color: '#1e293b', fontSize: '26px', fontWeight: '700' }}>{item.v}</h2>
          </div>
        ))}
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '2.2fr 1fr', gap: '25px' }}>
        <div style={{ background: '#fff', padding: '20px', borderRadius: '12px', boxShadow: '0 4px 12px rgba(0,0,0,0.03)' }}>
          <h3 style={{ margin: '0 0 20px 0', fontSize: '15px', color: '#1e293b', fontWeight: '600' }}>Enrollment Growth</h3>
          <div style={{ width: '100%', height: '260px' }}>
            <Line data={growthData} options={{ responsive: true, maintainAspectRatio: false }} />
          </div>
        </div>

        <div style={{ background: '#fff', padding: '20px', borderRadius: '12px', boxShadow: '0 4px 12px rgba(0,0,0,0.03)' }}>
          <h3 style={{ margin: '0 0 15px 0', fontSize: '15px', color: '#1e293b', fontWeight: '600' }}>Student Status</h3>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '5px' }}>
            {students.map((s, i) => (
              <div key={i} style={{ display: 'flex', justifyContent: 'space-between', padding: '12px 5px', borderBottom: '1px solid #f1f5f9', alignItems: 'center' }}>
                <span style={{ color: '#334155', fontSize: '14px', fontWeight: '500' }}>{s.name}</span>
                <span style={{ padding: '5px 12px', borderRadius: '20px', fontSize: '11px', fontWeight: '600', color: '#fff', background: s.status === 'Active' ? '#16a34a' : '#dc2626' }}>
                  {s.status}
                </span>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div style={{ background: '#fff', padding: '20px', borderRadius: '12px', boxShadow: '0 4px 12px rgba(0,0,0,0.03)' }}>
        <h3 style={{ margin: '0 0 15px 0', fontSize: '15px', color: '#1e293b', fontWeight: '600' }}>Upcoming Class Schedule</h3>
        <div style={{ overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', fontSize: '13px' }}>
            <thead>
              <tr style={{ borderBottom: '2px solid #e2e8f0' }}>
                <th style={{ padding: '10px', color: '#64748b' }}>Time</th>
                {schedule.days.map((day, i) => (
                  <th key={i} style={{ padding: '10px', color: '#64748b' }}>{day}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {schedule.slots.map((slot, i) => (
                <tr key={i} style={{ borderBottom: '1px solid #f1f5f9' }}>
                  <td style={{ padding: '12px 10px', fontWeight: '600', color: '#475569' }}>{slot.time}</td>
                  {schedule.days.map((day, j) => (
                    <td key={j} style={{ padding: '5px' }}>
                      {slot[day] && (
                        <span style={{ display: 'inline-block', padding: '6px 12px', borderRadius: '6px', fontSize: '12px', fontWeight: '500', color: '#fff', backgroundColor: slot[day].includes('Math') ? '#3b82f6' : slot[day].includes('Science') ? '#f59e0b' : slot[day].includes('English') ? '#10b981' : slot[day].includes('History') ? '#8b5cf6' : '#64748b' }}>
                          {slot[day]}
                        </span>
                      )}
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <div style={{ display: 'flex', gap: '15px', alignItems: 'center', justifyContent: 'space-between', marginTop: '10px' }}>
        <div style={{ display: 'flex', gap: '15px' }}>
          <button style={{ backgroundColor: '#16a34a', color: '#fff', border: 'none', padding: '10px 20px', borderRadius: '6px', cursor: 'pointer', fontWeight: '500', fontSize: '13px' }}>Manage Students</button>
          <button style={{ backgroundColor: '#fff', color: '#475569', border: '1px solid #e2e8f0', padding: '10px 20px', borderRadius: '6px', cursor: 'pointer', fontWeight: '500', fontSize: '13px' }}>Manage Teachers</button>
          <button style={{ backgroundColor: '#fff', color: '#475569', border: '1px solid #e2e8f0', padding: '10px 20px', borderRadius: '6px', cursor: 'pointer', fontWeight: '500', fontSize: '13px' }}>Create New Course</button>
        </div>
        
        <div style={{ fontSize: '12px', color: '#64748b', fontWeight: '400' }}>
          © 2026 AuraPen Saku. All rights reserved.
        </div>
      </div>
    </div>
  );
}
